package com.cyancoder.report.service;
import java.nio.charset.StandardCharsets;import java.util.Map;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import org.springframework.web.server.ResponseStatusException;
@Component public class TenantMembershipClient{private final RestClient client;private final String username,password;public TenantMembershipClient(RestClient.Builder b,@Value("${tenant-service.base-url:http://localhost:9129}")String url,@Value("${tenant-service.internal.username:tenant_internal}")String u,@Value("${tenant-service.internal.password:tenant_secret}")String p){client=b.baseUrl(url).build();username=u;password=p;}public void requireMembership(String tenant,String subject){if(tenant==null||tenant.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"X-Tenant-Key is required");try{Map<?,?> r=client.get().uri("/internal/tenants/{tenant}/members/{subject}/access",tenant,subject).headers(h->h.setBasicAuth(username,password,StandardCharsets.UTF_8)).retrieve().body(Map.class);if(r==null||!Boolean.TRUE.equals(r.get("active")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Tenant membership required");}catch(ResponseStatusException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Tenant membership service unavailable",e);}}}
